from pathlib import Path

SRC = Path("apps/Homebridge-Status/Homebridge Status.js")
src = SRC.read_text(encoding="utf-8")

src = src.replace('const APP_VERSION = "0.1.0";', 'const APP_VERSION = "0.1.1";', 1)
src = src.replace('// Homebridge Status v0.1.0', '// Homebridge Status v0.1.1', 1)

start = src.index('function esc(v){')
end = src.index('async function sendToWeb', start)

ui = r'''function esc(v){return String(v??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function nav(screen,icon,title,detail=""){return `<div class="navRow" onclick="showScreen('${screen}')"><div class="navLeft"><span class="navIcon">${icon}</span><span>${esc(title)}</span></div><div class="navRight"><span class="navDetail">${esc(detail)}</span><span class="chevron">›</span></div></div>`}
function settingsHTML(s){
  const hasPassword=passwordStored();
  const connectionDetail=s.primaryUrl&&s.fallbackUrl?"LAN + VPN":(s.primaryUrl?"LAN":(s.fallbackUrl?"VPN":"Nenastaveno"));
  const themeNames={system:"Systémový",dark:"Tmavě modrý",black:"Černý",custom:"Vlastní"};
  const colorsList=[
    ["backgroundColor","Pozadí"],["cardColor","Karty"],["textColor","Text"],["mutedColor","Vedlejší text"],
    ["accentColor","Akcent"],["okColor","OK"],["warningColor","Varování"],["failColor","Chyba"]
  ];
  const toggle=(id,title,detail="")=>`<label class="settingRow"><div class="rowText"><div class="rowTitle">${esc(title)}</div>${detail?`<div class="rowDetail">${esc(detail)}</div>`:""}</div><span class="switch"><input id="${id}" type="checkbox" ${s[id]?"checked":""} onchange="saveBySection('${id}')"><span class="slider"></span></span></label>`;
  const colorRows=colorsList.map(([id,label])=>`<div class="field"><label>${esc(label)}</label><div class="colorControl"><input id="${id}Picker" class="colorPicker" type="color" value="${esc(s[id])}" oninput="syncColorFromPicker('${id}')"><input id="${id}" class="colorCode" type="text" maxlength="7" value="${esc(s[id])}" onchange="syncColorFromText('${id}')"></div></div>`).join("");
  return `<!doctype html><html lang="cs"><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#111827;--panel2:#172033;--border:#2a3850;--text:#f8fafc;--muted:#94a3b8;--accent:#38bdf8;--ok:#86efac;--danger:#fb7185;--warn:#fde68a}*{box-sizing:border-box}html,body{margin:0;min-height:100%;color:var(--text);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-tap-highlight-color:transparent}html{background:#070b14}body{padding:calc(14px + env(safe-area-inset-top)) 14px calc(36px + env(safe-area-inset-bottom));max-width:680px;margin:auto;background:radial-gradient(circle at top,#172554 0,#0b1020 42%,#070b14 100%);background-attachment:fixed}.screen{display:none}.screen.active{display:block}.topbar{display:flex;align-items:center;justify-content:space-between;min-height:42px;margin:0 2px 8px}.back{border:0;background:transparent;color:var(--accent);font:inherit;font-size:16px;font-weight:750;padding:7px 0}.hero{background:rgba(17,24,39,.96);border:1px solid var(--border);border-radius:22px;padding:22px;margin-bottom:14px;box-shadow:0 24px 70px rgba(0,0,0,.45)}.eyebrow{display:inline-flex;align-items:center;padding:6px 10px;border:1px solid #1d4ed8;border-radius:999px;background:#0f1f46;color:#bfdbfe;font-size:.78rem;font-weight:700}.hero h1,.screenTitle{font-size:27px;line-height:1.15;margin:14px 0 6px;font-weight:800;letter-spacing:-.45px}.screenTitle{margin:5px 2px 6px}.hero p,.screenSub{color:var(--muted);font-size:14px;line-height:1.5;margin:0}.screenSub{margin:0 2px 14px}.updateStatus{min-height:17px;margin-top:8px;color:var(--muted);font-size:11px}.updateStatus.ok{color:var(--ok)}.updateStatus.error{color:var(--danger)}.sectionTitle{font-size:11px;color:#9fb3ce;text-transform:uppercase;letter-spacing:.1em;font-weight:800;margin:19px 9px 8px}.card{background:rgba(17,24,39,.96);border:1px solid var(--border);border-radius:18px;overflow:hidden;margin-bottom:13px;box-shadow:0 12px 34px rgba(0,0,0,.24)}.navRow,.settingRow{min-height:54px;display:flex;align-items:center;justify-content:space-between;padding:9px 14px;border-bottom:1px solid rgba(42,56,80,.85)}.navRow:last-child,.settingRow:last-child{border-bottom:0}.navRow:active{background:var(--panel2)}.navLeft{display:flex;gap:11px;align-items:center;font-size:15px;font-weight:700;min-width:0}.navIcon{width:26px;text-align:center}.navRight{display:flex;align-items:center;gap:8px}.navDetail,.rowDetail{font-size:12px;color:var(--muted)}.navDetail{max-width:190px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chevron{font-size:23px;color:#64748b}.rowText{min-width:0;padding-right:11px}.rowTitle{font-size:15px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rowDetail{margin-top:3px;line-height:1.35}.field{padding:12px 14px;border-bottom:1px solid rgba(42,56,80,.85)}.field:last-child{border-bottom:0}.field label{display:block;margin-bottom:7px;color:#dbeafe;font-size:.82rem;font-weight:650}input[type=text],input[type=url],input[type=number],input[type=password],select{width:100%;min-height:46px;border:1px solid var(--border);border-radius:12px;background:#0b1220;color:var(--text);padding:0 13px;font:inherit;font-size:15px;outline:none}.colorControl{display:grid;grid-template-columns:58px 1fr;gap:10px;align-items:center}.colorPicker{width:58px;height:46px;border:1px solid var(--border);border-radius:12px;background:#0b1220;padding:4px;overflow:hidden}.colorPicker::-webkit-color-swatch-wrapper{padding:0}.colorPicker::-webkit-color-swatch{border:0;border-radius:8px}.colorCode{text-transform:uppercase;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.previewGrid,.actionGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:13px}.actionGrid{grid-template-columns:1fr 1fr;padding:12px}.btn{min-height:48px;border:1px solid #1d4ed8;border-radius:13px;background:linear-gradient(135deg,#0369a1,#0284c7);color:#fff;font:inherit;font-weight:800;font-size:13px}.btn.secondary{background:#243149;border-color:var(--border)}.btn.danger{background:#3a1720;border-color:#6b2738;color:#fecdd3}.btn.full{grid-column:1/-1}.switch{position:relative;width:48px;height:28px;flex:0 0 48px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;border-radius:999px;background:#334155;transition:.2s}.slider:before{content:"";position:absolute;width:22px;height:22px;left:3px;top:3px;border-radius:50%;background:white;transition:.2s}.switch input:checked+.slider{background:#0a84ff}.switch input:checked+.slider:before{transform:translateX(20px)}.heroTop{display:flex;align-items:center;justify-content:space-between;gap:10px}.updateBtn{border:1px solid #1d4ed8;border-radius:999px;background:#0f1f46;color:#bfdbfe;padding:6px 10px;font:inherit;font-size:12px;font-weight:800}.hintBox{margin:0 0 13px;padding:12px 14px;border:1px solid var(--border);border-radius:14px;background:var(--panel2);color:#cbd5e1;font-size:13px;line-height:1.5}.hintBox b{color:#f8fafc}.status{min-height:20px;color:var(--ok);font-size:12px;padding:0 14px 12px}.status.error{color:var(--danger)}.status.warn{color:var(--warn)}.footer{color:#64748b;text-align:center;font-size:.76rem;margin:16px 4px 0}.helpItem{padding:14px;border-bottom:1px solid rgba(42,56,80,.85)}.helpItem:last-child{border-bottom:0}.helpTitle{font-size:15px;font-weight:750;margin-bottom:5px}.helpText{color:var(--muted);font-size:13px;line-height:1.5}@media(max-width:430px){.hero{padding:18px}.navDetail{max-width:128px}.previewGrid,.actionGrid{grid-template-columns:1fr}.btn.full{grid-column:auto}}
</style></head><body>
<div id="home" class="screen active"><div class="hero"><div class="heroTop"><span class="eyebrow">🏠 CaseyCZ · Scriptable</span><button class="updateBtn" onclick="post({action:'update'})">Aktualizace</button></div><h1>${esc(APP_NAME)}</h1><p>Stav Homebridge, výkon serveru a aktualizace na jednom místě.</p><div id="updateStatus" class="updateStatus">Aktuální verze · v${esc(APP_VERSION)}</div></div><div class="sectionTitle">Nastavení</div><div class="card">${nav("connection","🔗","Připojení",connectionDetail)}${nav("preview","👁","Náhled widgetu","Small / Medium / Large + Lock Screen")}${nav("appearance","🎨","Vzhled widgetu",themeNames[s.theme]||"Systémový")}${nav("behavior","⚙️","Chování",`${s.refreshMinutes} min`)}${nav("notifications","🔔","Notifikace",s.notificationEnabled?"Zapnuto":"Vypnuto")}${nav("help","❓","Nápověda","LAN → VPN fallback a nastavení")}</div><div class="footer">Změny se ukládají automaticky.</div></div>

<div id="connection" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Připojení</div><div class="screenSub">Homebridge adresa a přihlášení.</div><div class="hintBox"><b>Automatický fallback:</b> při každém obnovení se nejdřív zkusí primární LAN adresa. Když neodpoví, skript automaticky použije záložní VPN adresu.</div><div class="sectionTitle">Adresy</div><div class="card"><div class="field"><label>Primární adresa (LAN)</label><input id="primaryUrl" type="url" value="${esc(s.primaryUrl)}" placeholder="http://192.168.1.50:8581" onchange="saveConnection(false)"></div><div class="field"><label>Záložní adresa (VPN)</label><input id="fallbackUrl" type="url" value="${esc(s.fallbackUrl)}" placeholder="http://100.x.x.x:8581" onchange="saveConnection(false)"></div></div><div class="sectionTitle">Přihlášení</div><div class="card"><div class="field"><label>Uživatelské jméno</label><input id="username" type="text" value="${esc(s.username)}" placeholder="admin" onchange="saveConnection(false)"></div><div class="field"><label>Heslo ${hasPassword?"· uložené v Keychain":""}</label><input id="password" type="password" placeholder="${hasPassword?"Nech prázdné pro zachování":"Zadej heslo"}"></div>${toggle("allowInsecure","Povolit neověřený HTTPS certifikát","Použij jen pokud má Homebridge vlastní certifikát.")}</div><div class="actionGrid"><button class="btn full" onclick="saveConnection(true)">Otestovat připojení</button><button class="btn secondary full" onclick="removePass()">Smazat uložené heslo</button></div><div id="connectionStatus" class="status"></div></div>

<div id="preview" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Náhled widgetu</div><div class="screenSub">Reálná data z právě dostupné LAN nebo VPN adresy.</div><div class="sectionTitle">Domovská obrazovka</div><div class="previewGrid"><button class="btn" onclick="preview('small')">Small</button><button class="btn" onclick="preview('medium')">Medium</button><button class="btn" onclick="preview('large')">Large</button></div><div class="sectionTitle">Lock Screen</div><div class="previewGrid"><button class="btn secondary" onclick="preview('accessoryInline')">Inline</button><button class="btn secondary" onclick="preview('accessoryCircular')">Circular</button><button class="btn secondary" onclick="preview('accessoryRectangular')">Rectangular</button></div><div id="previewStatus" class="status"></div></div>

<div id="appearance" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Vzhled widgetu</div><div class="screenSub">Stejný systém vzhledu jako v Home Dashboardu.</div><div class="card"><div class="field"><label>Název widgetu</label><input id="widgetTitle" type="text" maxlength="40" value="${esc(s.widgetTitle)}" onchange="saveAppearance()"></div><div class="field"><label>Motiv</label><select id="theme" onchange="saveAppearance()"><option value="system" ${s.theme==="system"?"selected":""}>Systémový</option><option value="dark" ${s.theme==="dark"?"selected":""}>Tmavě modrý</option><option value="black" ${s.theme==="black"?"selected":""}>Černý</option><option value="custom" ${s.theme==="custom"?"selected":""}>Vlastní</option></select></div></div><div class="sectionTitle">Viditelnost</div><div class="card">${toggle("showGraphs","Grafy CPU / RAM")}${toggle("showTemperature","Teplota CPU")}${toggle("showUptime","Uptime Raspberry Pi / UI")}${toggle("showUpdated","Čas poslední kontroly")}${toggle("showRoute","Zobrazit LAN / VPN")}</div><div class="sectionTitle">Vlastní barvy</div><div class="card">${colorRows}</div><div class="actionGrid"><button class="btn secondary full" onclick="resetAppearance()">Obnovit výchozí vzhled</button></div></div>

<div id="behavior" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Chování</div><div class="screenSub">Obnova widgetu, timeout a ignorované aktualizace.</div><div class="card"><div class="field"><label>Obnova widgetu</label><div class="rowDetail" style="margin-bottom:8px">iOS může widget obnovit později než v požadovaném intervalu.</div><select id="refreshMinutes" onchange="saveBehavior()">${[5,15,30,60,120,180].map(v=>`<option value="${v}" ${s.refreshMinutes===v?"selected":""}>${v} min</option>`).join("")}</select></div><div class="field"><label>Timeout požadavku (s)</label><input id="requestTimeout" type="number" min="1" max="30" value="${s.requestTimeout}" onchange="saveBehavior()"></div></div><div class="sectionTitle">Aktualizace Homebridge</div><div class="card"><div class="field"><label>Ignorovat aktualizace</label><div class="rowDetail" style="margin-bottom:8px">Přesný npm název pluginu, případně HOMEBRIDGE_UTD nebo NODEJS_UTD. Více položek odděl čárkou.</div><input id="ignoredUpdates" type="text" value="${esc(s.ignoredUpdates)}" placeholder="homebridge-plugin, NODEJS_UTD" onchange="saveBehavior()"></div></div></div>

<div id="notifications" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Notifikace</div><div class="screenSub">Výpadky a dostupné aktualizace.</div><div class="card">${toggle("notificationEnabled","Zapnout notifikace")}${toggle("recoveryNotifications","Upozornit při návratu do normálu")}<div class="field"><label>Stejnou chybu zopakovat nejdříve za</label><select id="notificationIntervalHours" onchange="saveNotifications()">${[0,1,6,12,24,48,72,168].map(v=>`<option value="${v}" ${s.notificationIntervalHours===v?"selected":""}>${v===0?"Pokaždé":v+" h"}</option>`).join("")}</select></div></div></div>

<div id="help" class="screen"><div class="topbar"><button class="back" onclick="showScreen('home')">‹ Zpět</button><span></span></div><div class="screenTitle">Nápověda</div><div class="screenSub">Jak Homebridge Status funguje.</div><div class="card"><div class="helpItem"><div class="helpTitle">1. Primární LAN adresa</div><div class="helpText">Použij běžnou domácí adresu Homebridge, například http://192.168.1.50:8581. Ta má vždy přednost.</div></div><div class="helpItem"><div class="helpTitle">2. Záložní VPN adresa</div><div class="helpText">Sem dej adresu dostupnou přes VPN, například Tailscale. Použije se automaticky pouze tehdy, když LAN adresa neodpoví.</div></div><div class="helpItem"><div class="helpTitle">3. Přihlášení</div><div class="helpText">Skript používá stejné Homebridge UI API jako původní funkční widget. Heslo je uloženo pouze v Scriptable Keychain.</div></div><div class="helpItem"><div class="helpTitle">4. Staré nastavení</div><div class="helpText">Při prvním spuštění se skript pokusí převzít adresu, uživatele, heslo a notifikace ze starého black.json.</div></div><div class="helpItem"><div class="helpTitle">5. Velikosti widgetu</div><div class="helpText">Podporované jsou Small, Medium, Large a Lock Screen Inline, Circular a Rectangular.</div></div></div></div>

<script>
let state=${JSON.stringify(s)};window.__nativeQueue=[];
function post(m){window.__nativeQueue.push(Object.assign({},m,{nonce:Date.now()+Math.random()}))}
function showScreen(id){document.querySelectorAll('.screen').forEach(function(x){x.classList.remove('active')});document.getElementById(id).classList.add('active')}
function collect(){Object.keys(state).forEach(function(k){var e=document.getElementById(k);if(!e)return;if(e.type==='checkbox')state[k]=e.checked;else if(e.type==='number')state[k]=Number(e.value);else state[k]=e.value});return state}
function save(){collect();post({action:'save',settings:state})}
function saveConnection(test){collect();var p=document.getElementById('password').value;post({action:test?'test':'saveConnection',settings:state,password:p});if(test)document.getElementById('password').value=''}
function removePass(){post({action:'removePassword'})}
function preview(f){collect();document.getElementById('previewStatus').textContent='Načítám…';post({action:'preview',family:f,settings:state})}
function saveAppearance(){collect();state.useCustomColors=state.theme==='custom';post({action:'save',settings:state})}
function saveBehavior(){collect();post({action:'save',settings:state})}
function saveNotifications(){collect();post({action:'save',settings:state})}
function saveBySection(id){if(id==='allowInsecure')saveConnection(false);else if(id==='notificationEnabled'||id==='recoveryNotifications')saveNotifications();else saveAppearance()}
function syncColorFromPicker(id){var p=document.getElementById(id+'Picker'),t=document.getElementById(id);if(!p||!t)return;t.value=p.value.toUpperCase();state[id]=t.value;state.theme='custom';state.useCustomColors=true;document.getElementById('theme').value='custom';post({action:'save',settings:state})}
function syncColorFromText(id){var t=document.getElementById(id),p=document.getElementById(id+'Picker');if(!t||!p)return;var v=String(t.value||'').trim().toUpperCase();if(v&&v.charAt(0)!=='#')v='#'+v;t.value=v;if(/^#[0-9A-F]{6}$/.test(v)){p.value=v;state[id]=v;state.theme='custom';state.useCustomColors=true;document.getElementById('theme').value='custom';post({action:'save',settings:state})}}
function resetAppearance(){Object.assign(state,{theme:'system',useCustomColors:false,backgroundColor:'#0B1020',cardColor:'#141B2D',textColor:'#F8FAFC',mutedColor:'#94A3B8',accentColor:'#0A84FF',okColor:'#34C759',warningColor:'#FF9F0A',failColor:'#FF453A',showGraphs:true,showTemperature:true,showUptime:true,showUpdated:true,showRoute:true});post({action:'save',settings:state});location.reload()}
window.__native=function(m){if(!m)return;if(m.action==='connection'){var e=document.getElementById('connectionStatus');if(e){e.textContent=m.text||'';e.className='status '+(m.ok?'':'error')}}if(m.action==='previewDone'){var p=document.getElementById('previewStatus');if(p)p.textContent=''}if(m.action==='update'){var u=document.getElementById('updateStatus');if(u){u.textContent=m.text||'';u.className='updateStatus '+(m.ok?'ok':'error')}}if(m.action==='password'){var x=document.getElementById('connectionStatus');if(x)x.textContent=m.text||''}};
</script></body></html>`
}
'''

src = src[:start] + ui + src[end:]
SRC.write_text(src, encoding="utf-8")
print("Homebridge Status UI refactored to Home Dashboard style")
